    // small pitch split so the three playable characters remain distinct.
    if (Mesh == SkeletalMesh'HPModels.skronPlayerMesh')
    {
        PlayOwnedSound(Sound'HPSounds.Har_Emotes.jump1', SLOT_Talk, 1.35, False, 1200.0, 0.88);
        return;
    }

    if (Mesh == SkeletalMesh'HPModels.skhermionePlayerMesh')
    {
